// `#[derive(Clone)]` of the rustc_ast types, generated by tools/codegen as `clone_<Type>` (PORTING §5).
// Owned data (`Box`, `Vec`, `ThinVec`, `Option`, nested structs/enums) is copied; `Lrc`/`Arc` fields
// (`LazyAttrTokenStream`'s inner, `TokenStream`'s `Arc<Vec<TokenTree>>`) are shared; interned handles
// (`Span`, `Symbol`, `NodeId`, `Ident`) and string-literal enums are the same value. Copy structs
// (`Lifetime`, `DelimSpan`) are copied too, since generated `MutWalkable` impls edit them in place.
import { expect, test } from "bun:test";
import { clone_Mutability } from "../rustc_ast_ir/lib.ts";
import type { Span } from "../rustc_span/span_encoding.ts";
import { Ident, type Symbol } from "../rustc_span/symbol.ts";
import {
  clone_Expr,
  clone_Lifetime,
  clone_Pat,
  clone_Ty,
  DelimArgs,
  Expr,
  type Lifetime,
  MacCall,
  Pat,
  Path,
  PathSegment,
  Ty,
} from "./ast.ts";
import type { NodeId } from "./node_id.ts";
import { DelimSpan, LazyAttrTokenStream, type LazyAttrTokenStreamInner, TokenStream, type TokenTree } from "./tokenstream.ts";

const sp = (n: number) => n as Span;
const nid = (n: number) => n as NodeId;
const sym = (n: number) => n as Symbol;
const path = (id: number) => new Path(sp(1), [new PathSegment(new Ident(sym(9), sp(2)), nid(id), undefined)]);

test("Ty (manual impl Clone, ast.rs:2455): deep copy of the kind, ids and spans kept, class kept", () => {
  const p = path(3);
  const t = new Ty(nid(1), { $: "Path", _0: undefined, _1: p }, sp(4));
  const c = clone_Ty(t);
  expect(c).not.toBe(t);
  expect(c).toBeInstanceOf(Ty);
  expect(c).toEqual(t);
  const ck = c.kind as { _1: Path };
  expect(ck._1).not.toBe(p);
  expect(ck._1).toBeInstanceOf(Path);
  expect(ck._1.segments).not.toBe(p.segments);
  expect(ck._1.segments[0]).not.toBe(p.segments[0]);
  expect(ck._1.segments[0]!.ident).toBe(p.segments[0]!.ident); // Ident: Copy handle, shared
  ck._1.segments.push(new PathSegment(new Ident(sym(10), sp(0)), nid(5), undefined));
  expect(p.segments.length).toBe(1); // the original ThinVec is untouched
});

test("Expr: attrs/kind copied; LazyAttrTokenStream and TokenStream share their Arc'd contents", () => {
  const inner = { opaque: "lazy" } as unknown as LazyAttrTokenStreamInner;
  const trees: TokenTree[] = [];
  const ds = new DelimSpan(sp(5), sp(6));
  const mac = new MacCall(path(3), new DelimArgs(ds, { $: "Parenthesis" }, new TokenStream(trees)));
  const e = new Expr(nid(1), { $: "MacCall", _0: mac }, sp(7), [], new LazyAttrTokenStream(inner));
  const c = clone_Expr(e);
  expect(c).toBeInstanceOf(Expr);
  expect(c).toEqual(e);
  expect(c.attrs).not.toBe(e.attrs);
  // `tokens: Option<LazyAttrTokenStream>`: a new handle around the same `Arc` (tokenstream.rs:114)
  expect(c.tokens).not.toBe(e.tokens);
  expect(c.tokens!._0).toBe(inner);
  const cm = (c.kind as { _0: MacCall })._0;
  expect(cm).not.toBe(mac);
  expect(cm.args).not.toBe(mac.args);
  // `TokenStream(Arc<Vec<TokenTree>>)`: the vector is shared, not copied
  expect(cm.args.tokens).not.toBe(mac.args.tokens);
  expect(cm.args.tokens._0).toBe(trees);
  // `DelimSpan` is Copy, but an object the MutVisitor edits in place: copied
  expect(cm.args.dspan).not.toBe(ds);
  expect(cm.args.dspan).toEqual(ds);
});

test("Copy structs are copied, fieldless enums and handles are the same value", () => {
  const l: Lifetime = { id: nid(1), ident: new Ident(sym(2), sp(3)) };
  const lc = clone_Lifetime(l);
  expect(lc).not.toBe(l);
  expect(lc).toEqual(l);
  expect(lc.ident).toBe(l.ident);
  expect(clone_Mutability("Mut")).toBe("Mut");
});

test("Pat: Option<Box<Pat>> and ThinVec<Pat> are deep copies; unit variants stay shared singletons", () => {
  const wild = new Pat(nid(3), { $: "Wild" }, sp(0));
  const p = new Pat(nid(1), { $: "Tuple", _0: [wild] }, sp(0));
  const c = clone_Pat(p);
  const elems = (c.kind as { _0: Pat[] })._0;
  expect(elems).not.toBe((p.kind as { _0: Pat[] })._0);
  expect(elems[0]).not.toBe(wild);
  expect(elems[0]!.kind).toBe(wild.kind); // `PatKind::Wild`: no data to copy
  expect(c).toEqual(p);
});
